    induction l <;> simp_all +decide [ List.filter_cons, List.flatMap ];
    split_ifs <;> simp_all +decide [ Function.comp_def ];
    · exact List.filter_congr fun x hx => by specialize h _ _ hx; aesop;
    · grind

