    contrapose! h_sorted;
    obtain ⟨ k, hk ⟩ := hx;
    by_cases h_cases : k.val < n.val + 1;
    · use ⟨ k, by
        exact k.2 ⟩, ⟨ n, by
        exact lt_of_lt_of_le n.2 ( by simp ) ⟩
      generalize_proofs at *;
      grind;
    · use ⟨ n + 1, by
        grind ⟩, k
      generalize_proofs at *;
      grind

